def creer_niveaux(apps, schema_editor):
    NiveauScolaire = apps.get_model('api', 'NiveauScolaire')
    for code, lib, lib_en, ordre in NIVEAUX_TECHNIQUES:
        NiveauScolaire.objects.update_or_create(code_niveau=code, defaults={
            'lib_niveau': lib, 'lib_en': lib_en, 'type_etab': 'SECONDAIRE',
            'systeme': 'FRANCOPHONE', 'ordre': ordre,
        })


def retirer_niveaux(apps, schema_editor):
    apps.get_model('api', 'NiveauScolaire').objects.filter(
        code_niveau__in=[n[0] for n in NIVEAUX_TECHNIQUES]).delete()


